-- chair-step: inverse of read_lane_v2_b3_53_seo_keyword_facet — un-enrolls seo.keyword_facet from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'seo' and table_name = 'keyword_facet' and is_active);
select iam.apply_rls('seo', 'keyword_facet', (select token from platform.entity_types where schema_name = 'seo' and table_name = 'keyword_facet' and is_active), (select rls_variant from platform.entity_types where schema_name = 'seo' and table_name = 'keyword_facet' and is_active));
